                    d = depot if j == n - 1 else rt[j + 1]
                    cur = matrix[a][b] + matrix[c][d]
                    new = matrix[a][c] + matrix[b][d]
                    delta = cur - new
                    if delta > best_delta:
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i is None or best_delta <= 0:
                break
            rt = rt[:best_i] + list(reversed(rt[best_i:best_j + 1])) + rt[best_j + 1:]
            improved_any = True
        return rt, improved_any

    improved = True
    while improved:
        improved = False
        for ridx in range(len(sol_routes)):
            rt, did = two_opt_on_route(sol_routes[ridx])
            if did:
                sol_routes[ridx] = rt
                improved = True

    # Inter-route relocation (as in incumbent, limited)
    def delta_relocate(from_rt, to_rt, pos_from, pos_to):
        x = from_rt[pos_from]
        n = len(from_rt)
        prev_from = from_rt[pos_from - 1] if pos_from - 1 >= 0 else depot
        next_from = from_rt[pos_from + 1] if pos_from + 1 < n else depot
        old_from = matrix[prev_from][x] + matrix[x][next_from]
        new_from = matrix[prev_from][next_from]

        m = len(to_rt)
        if pos_to == 0:
            prev_to = depot
            next_to = to_rt[0] if m > 0 else depot
            old_to = 0 if m == 0 else matrix[prev_to][next_to]
            new_to = matrix[prev_to][x] + matrix[x][next_to]
        elif pos_to == m:
            prev_to = to_rt[m - 1] if m > 0 else depot
            next_to = depot
            old_to = 0 if m == 0 else matrix[prev_to][next_to]
            new_to = matrix[prev_to][x] + matrix[x][next_to]
        else:
            prev_to = to_rt[pos_to - 1]
            next_to = to_rt[pos_to]
            old_to = matrix[prev_to][next_to]
            new_to = matrix[prev_to][x] + matrix[x][next_to]

        return (old_from - new_from) + (old_to - new_to)

    max_moves = 60 if len(sol_routes) > max(2, int(vehicle_hint * 0.8)) else 30
    moves_done = 0
    while moves_done < max_moves:
        best_found = False
        for i in range(len(sol_routes)):
            from_rt = sol_routes[i]
            if len(from_rt) == 0:
                continue
            from_load = route_load(from_rt)
            for pf in range(len(from_rt)):
                x = from_rt[pf]
                for j in range(len(sol_routes)):
                    if i == j:
                        continue
                    to_rt = sol_routes[j]
                    to_load = route_load(to_rt)
                    if to_load + demands[x] > capacity:
                        continue
                    m = len(to_rt)
                    for pt in range(m + 1):
                        gain = delta_relocate(from_rt, to_rt, pf, pt)
                        if gain > 0:
                            sol_routes[i] = from_rt[:pf] + from_rt[pf + 1:]
                            sol_routes[j] = to_rt[:pt] + [x] + to_rt[pt:]
                            if sol_routes[i] == []:
                                sol_routes.pop(i)
                            moves_done += 1
                            best_found = True
                            break
                    if best_found:
                        break
                if best_found:
                    break
            if best_found:
                break
        if not best_found:
            break

    # Inter-route 1-1 swap (targeted small exchange to reduce stubborn bottlenecks)
    def delta_swap(rtA, rtB, iA, iB):
        x = rtA[iA]
        y = rtB[iB]

        a_prev = rtA[iA - 1] if iA > 0 else depot
        a_next = rtA[iA + 1] if iA + 1 < len(rtA) else depot
        b_prev = rtB[iB - 1] if iB > 0 else depot
        b_next = rtB[iB + 1] if iB + 1 < len(rtB) else depot

        old = matrix[a_prev][x] + matrix[x][a_next] + matrix[b_prev][y] + matrix[y][b_next]
        new = matrix[a_prev][y] + matrix[y][a_next] + matrix[b_prev][x] + matrix[x][b_next]
        return old - new  # positive is improvement

    swap_limit = 40
    swap_done = 0
    while swap_done < swap_limit:
        applied = False
        for i in range(len(sol_routes)):
            for j in range(i + 1, len(sol_routes)):
                A = sol_routes[i]
                B = sol_routes[j]
                if not A or not B:
                    continue
                loadA = route_load(A)
                loadB = route_load(B)
                # Deterministic order: smaller indices first
                for iA in range(len(A)):
                    x = A[iA]
                    for iB in range(len(B)):
                        y = B[iB]
                        if (loadA - demands[x] + demands[y] > capacity) or (loadB - demands[y] + demands[x] > capacity):
                            continue
                        gain = delta_swap(A, B, iA, iB)
                        if gain > 0:
                            sol_routes[i] = A[:iA] + [y] + A[iA + 1:]
                            sol_routes[j] = B[:iB] + [x] + B[iB + 1:]
                            swap_done += 1
                            applied = True
                            break
                    if applied:
                        break
                if applied:
                    break
            if applied:
                break
        if not applied:
            break

    # Final cleanup and feasibility-oriented fallback check
    cleaned = []
    used = set()
    for rt in sol_routes:
        if rt:
            cleaned.append(rt)
            for n in rt:
                used.add(n)

    if used != customers:
        # Conservative fallback: greedy build
        return build_greedy()

    # Deterministic capacity cleanup (should already be feasible)
    final = []
    for rt in cleaned:
        if route_load(rt) <= capacity:
            final.append(rt)
        else:
            return build_greedy()

    return final
